    display: flex;
    align-items: center;
    justify-content: center;
}

.medical-scheduler.e-schedule img {
    height: 35px;
    width: 35px;
}

/* Buffer pill (before/after) */
.buffer-minimal {
    width: 100%;
    height: 100%;
    justify-content: flex-start;
    align-items: center;
    gap: 6px;
    overflow: hidden;
}

.e-day-wrapper .buffer-minimal {
  width: 100%;
  height: fit-content;
  display: grid;
  justify-content: center;
  align-items: center;
  gap: 6px;
  overflow: hidden;
}

